pub fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    // Lower_bound-style binary search:
    // find the smallest index i such that arr[i] >= target.
    let mut lo: usize = 0;
    let mut hi: usize = arr.len(); // exclusive

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // lo is the first position where arr[lo] >= target (or arr.len()).
    if lo < arr.len() && arr[lo] == target {
        Some(lo)
    } else {
        None
    }
}

